using Marketplace.Domain.Common; namespace Marketplace.Domain.Finance; public enum SellerBalanceHoldStatus:byte{Active=1,Released=2,Consumed=3} public sealed class SellerBalanceHold:Entity<long>{private SellerBalanceHold(){}public long SellerId{get;private set;}public long? OrderId{get;private set;}public long AmountIRR{get;private set;}public string Reason{get;private set;}=null!;public SellerBalanceHoldStatus Status{get;private set;}public static SellerBalanceHold Create(long id,long sellerId,long? orderId,long amount,string reason){if(amount<=0||string.IsNullOrWhiteSpace(reason))throw new DomainException("Invalid balance hold.");return new(){Id=id,SellerId=sellerId,OrderId=orderId,AmountIRR=amount,Reason=reason.Trim(),Status=SellerBalanceHoldStatus.Active};}public void Release(){if(Status!=SellerBalanceHoldStatus.Active)throw new DomainException("Hold is not active.");Status=SellerBalanceHoldStatus.Released;}public void Consume(){if(Status!=SellerBalanceHoldStatus.Active)throw new DomainException("Hold is not active.");Status=SellerBalanceHoldStatus.Consumed;}}
